35	gk_field_calc_ambi_pot_sheath_vals(gkyl_gyrokinetic_app *app, struct gk_field *field)
36	{
37	  // Note that the M0 moment of boundary fluxes along z should
38	  // be stored in the ghost cells of m0.marr at this point.
39	  int idx_par = app->cdim-1;
40	  int off = 2*idx_par;
41	
42	  int comm_sz;
43	  gkyl_comm_get_size(app->comm, &comm_sz);
44	
45	  for (int i=0; i<app->num_species; ++i) {
46	    struct gk_species *s = &app->species[i];
47	
48	    if (s->info.charge > 0.0) {
49	      // Assumes symmetric sheath BCs for now only in 1D
50	      // NOTE: this relies on the accumulate_rho_c calling gk_species_moment_calc(s->m0)
51	      // to calculate the particle flux and place it in the ghost cells of s->m0.marr.
52	      gkyl_ambi_bolt_potential_sheath_calc(field->ambi_pot, GKYL_LOWER_EDGE, 
53	        &app->local_lower_skin[idx_par], &app->local_lower_ghost[idx_par], app->gk_geom->geo_int.cmag, 
54	        app->gk_geom->geo_int.jacobtot_inv, s->m0.marr, field->rho_c, s->m0.marr, field->sheath_vals[off]);
