64	      gkyl_array_copy_range_to_range(field->sheath_vals[off+1], field->sheath_vals[off+1],
65	        &app->local_lower_ghost[idx_par], &app->local_upper_ghost[idx_par]);
66	      gkyl_array_accumulate(field->sheath_vals[off], 1., field->sheath_vals[off+1]);
