73	gk_field_rhs_boltzmann(struct gkyl_gyrokinetic_app *app, struct gk_field *field)
74	{
75	  // Compute sheath density n_i,s and potential phi_s = (Te/e)*ln(n_i,s*v_te/(sqrt(2*pi)*Gamma_i)).
76	  gk_field_calc_ambi_pot_sheath_vals(app, app->field);
77	
78	  // Solve phi = phi_s + (Te/e)*ln(n_i/n_i,s).
79	  gkyl_ambi_bolt_potential_phi_calc(field->ambi_pot, &app->local, &app->local_ext,
80	    field->rho_c, field->sheath_vals[2*(app->cdim-1)], field->phi_smooth);
81	
82	  // Smooth the potential along z.
83	  gk_field_fem_projection_par(app, field, field->phi_smooth, field->phi_smooth);
84	}
